def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        raise Blocked("communities unavailable")
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("communities request failed")
    return all(isinstance(item, dict) and bool(item.get("id")) and bool(item.get("name")) for item in data) and isinstance(responseBody.get("message"), str) and bool(responseBody.get("requestId"))

