def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list):
        return False
    matches = [it for it in items if isinstance(it, dict) and it.get("id") == globalParam.get("M")]
    if statusCode != 200 or responseBody.get("code") != 0 or len(items) != 1 or len(matches) != 1:
        return False
    msg = matches[0]
    created = msg.get("createdAt") or ""
    return (msg.get("clientMessageId") == globalParam.get("k")
            and msg.get("content") == "集合时间确认"
            and msg.get("recalled") is False
            and isinstance(created, str) and created.endswith("Z") and len(created) == 20
            and bool(responseBody.get("requestId")))

